	\section{Preliminaries} \label{sec:preliminaries}
	\subsection{General Notation}
	We denote the set $\{1,\ldots,n\}$ by $[n]$ and let $\F_q$ be the finite field of order $q$, where $q$ is a prime power.  

    \subsection{Local Polynomial Profiles}
    Fix $a\in \N$. A tuple of polynomials $(P_1,\dots, P_a)\in \F_q[X]^a$ is said to be \deffont{$k$-bounded} if $\deg(P_i)< k$ for every $1\le i\le a$. If $S\subseteq \F_q[X]^a$ consists of $k$-bounded tuples, we say that $S$ itself is \deffont{$k$-bounded}.

    For $\alpha\in \F_q$ and $\bP = \inparen{P_1,\dots, P_a}\in \F_q[X]^a$, we denote the evaluation $\bP(\alpha) := \inparen{P_1(\alpha),\dots, P_a(\alpha)}$. 

    Let $\F_q(X)$ denote the field of univariate rational functions over $\F_q$. We naturally embed $\F_q$ in $\F_q(X)$ by considering each $\alpha \in\F_q$ as the constant rational function $\alpha \in \F_q(X)$. By abuse of notation, both objects will be denoted by $\alpha$. Note that every $\F_q(X)$-linear space is also $F_q$-linear. Throughout this section we use $\dims $ and $\diml $ to refer to linear dimension of $\F_q$ and $\F_q(X)$, respectively. We similarly distinguish between $\spns$ and $\spnl$, and between $\ranks$ and $\rankl$. 

     \begin{definition}\label{def:polyMap}
            An $\F_q(X)$-linear map $\psi:\F_q(X)^b\to \F_q(X)^a$ is said to be \deffont{polynomial} if $\psi\inparen{\F_q[X]^b} \subseteq \F_q[X]^a$. In other words, $\psi$ is \deffont{polynomial} if it is represented in the standard basis by a matrix with polynomial entries. We use $\deg \psi$ to denote the maximum degree (as a polynomial) of an entry in this matrix.
        \end{definition}

	\begin{definition} \label{def:polyProfiles}
		A \deffont{$b$-local polynomial profile} is a sequence $\Psi = \inparen{\psi_1,\dots \psi_n}$ of $\F_q(X)$-linear polynomial maps $\psi_i : \F_q(X)^b \to \F_q(X)^{b_i}$ (for some $b_1,\dots, b_n\in \N$). We denote $\deg \Psi = \max_{1\le i\le n} \deg \psi_i$.

        Let $\balpha = \inparen{\alpha_1,\dots,\alpha_n} \in \F_q^n$. A tuple of polynomials $(P_1,\dots, P_b)$ is said to \deffont{satisfy} $(\Psi,\balpha)$ if for every $i\in [n]$ it holds that
		\begin{equation}\label{eq:PsiConstraint}
			\inparen{\psi_i\inparen{P_1,\dots, P_b}}(\alpha_i)=0\eperiod
		\end{equation}
        For an $\F_q$-linear space $S\subseteq \F_q[X]^b$, we denote $$S[\Psi,\balpha] = \inset{\bP\in S\mid \bP\textrm{ satisfies }(\Psi,\balpha)}\eperiod$$
        \end{definition}

        \begin{definition}[Strength]\label{def:strength}
            For an $\F_q(X)$-linear subspace $U \subseteq \F_q(X)^b$ and a polynomial map $\psi$, we denote $\rf_U(\psi) \coloneqq \diml  \psi(U)$. Note that when $U = \F_q(X)^b$, we have $\rf_U(\psi) = \rankl  \psi$.

            For an $\F_q(X)$-linear subspace $U\subseteq\F_q(X)^b$ and a polynomial profile $\Psi = \inparen{\psi_1,\dots \psi_n}$, we denote $\rf_U(\Psi) = \sum_{i=1}^n \rf_U(\psi_i)$.
        \end{definition}

    \begin{definition}
        Given $T,U\subseteq \F_q(X)^b$, where $U$ is an $\F_q(X)$-linear subspace, we say that $U$ is \deffont{$T$-live} if $\spnl (T\cap U) = U$. Otherwise, we say that $U$ is \deffont{$T$-dead}.
    \end{definition}

    \subsection{A Potential Function for Local Polynomial Profiles}
	Given an $\F_q(X)$-linear space $W\subseteq \F_q(X)^b$, we denote
	$$d_W(S) := \dims \inparen{S\cap W}$$
	and
	$$\pot_W\inparen{S,\Psi} := d_W(S) - \rf_W(\Psi)\eperiod$$

	For $0\le i \le n$, denote $\balpha_\ut i = \inparen{\alpha_1,\dots,\alpha_i}$. Also, $\Psi_\ut i = \inparen{\psi_1,\dots, \psi_i}$ and $\Psi_\uf i = \inparen{\psi_{i},\dots, \psi_n}$. 

    \begin{lemma}[If $\pot_W(S,\Psi)$ is very negative then $W$ is probably $S\inbrak{\Psi,\balpha}$-dead]\label{lem:LikelyToNotContainW}
		Let $S\subseteq \F_q[X]^b$ be a $k$-bounded $\F_q$-linear space ($k\in \N$). Let $\Psi = \inparen{\psi_1,\dots, \psi_n}$ be a $b$-local polynomial profile and let $g = \deg \Psi$. Let $W \subseteq \F_q(X)^b$ be an $\F_q(X)$-linear space and let $D = \diml  W$. Let $L > 0$ and suppose that $\pot_W\inparen{S,\Psi}\le -L$. Then,
		\begin{equation}\label{eq:ProbOfSpannnigW}
			\PROver{\balpha\sim \uniform\inparen{\F_q^n}}{W\textnormal{ is }S[\Psi,\balpha]\textnormal{-live}} \le \binom n {\ceil{\frac{L}D}}\cdot\inparen{\frac{(k+g)D}{q}}^{\ceil{\frac{L}D}}\eperiod
		\end{equation}
		Furthermore, let $0 \le L'\le L$ and let $E_{L'}$ denote the event that at least one of the following occurs:
        \begin{itemize}
              \item $W$ is $S[\Psi,\balpha]$-live \emph {OR}
              \sloppy
              \item Let $0\le s\le n$ denote the minimum index for which $W$ is $S[\Psi_\ut s,\balpha_\ut s]$-dead. Also, $\pot_W\inparen{S\inbrak{\Psi_\ut{s}, \balpha_{\ut{s}}},\Psi_{\uf{s+1}}} \ge -L'$ holds.
        \end{itemize}
        Then, for all $0\le L'\le L$,
		\begin{equation}\label{eq:ProbOfSmallGamma}
			\PROver{\balpha\sim \uniform(\F_q^n)}{E_{L'}} \le \binom n {\ceil{\frac{L-L'}{D}}}\cdot \inparen{\frac{(k+g)D}{q}}^{\ceil{\frac{L-L'}D}}\eperiod
		\end{equation}
	\end{lemma}

	\begin{lemma}[The change in $\pot_W$ in a single step]\label{lem:GammaChange}
		Let $\Psi = \inparen{\psi_1,\dots, \psi_n}$ be a $b$-local polynomial profile, let $S\subseteq \F_q[X]^b$ be a $k$-bounded $\F_q$-linear space ($k\in \N$). Let $W \subseteq \F_q(X)^b$ be  an $S$-live $\F_q(X)$-linear space.

        Given $\alpha \in \F_q$, write $p = \pot_W(S,\Psi)$ and $p_\alpha = \pot_W(S[\psi_1, \alpha],\Psi_\uf 2)$. Also, let $D = \diml  \psi_1(W)$ and $g = \deg \psi_1$.

        Then, $$p\le p_\alpha \le p +D$$ 
        for all $\alpha \in \F_q$. Furthermore,
		$$\PROver{\alpha\sim \uniform(\F_q)}{p_\alpha = p} \ge 1 - \frac{(k+ g)\cdot D}q\eperiod$$
	\end{lemma}
