\begin{lemma}[If $\pot_U(S,\Psi)$ is very negative for all $U$ then $S\inbrak{\Psi,\balpha}$ is probably trivial]\label{lem:LikelyToBeEmpty}
		Let $S\subseteq \F_q[X]^b$ be a $k'$-bounded $\F_q$-linear space ($k'\in \N$). Let $W = \spnl  S$ and write $D_W = \diml  W$. Let $\Psi = \inparen{\psi_1,\dots, \psi_n}$ be a $b$-local polynomial profile and denote $g := \max\inset{\deg \Psi, b\cdot k'}$. 
          Suppose that there exists some \begin{equation}\label{eq:lambdaLB}
			\lambda \ge 2\cdot D_W\cdot(D_W+1)
		\end{equation} such that
		\begin{equation} \label{eq:potentialLB}
			\pot_U\inparen{S,\Psi} \le -\lambda \cdot \diml U
		\end{equation}
		for every $S$-live $\F_q(X)$-linear subspace $U\subseteq W$.
        Then,
		$$
		\PR{S\inbrak{\Psi,\balpha} \supsetneq \{0\}} \le  \inparen{2^{D_W}-1}\cdot \inparen{\frac{4e \cdot 2^{D_W} \cdot b^{2D_W}{\cdot g \cdot n}}{\lambda\cdot q}}^{\frac{\lambda}{2D_W}}\eperiod
		$$
