\begin{proof}[Proof of \cref{lem:LikelyToBeEmpty}]
        Throughout this proof, if $U$ is an $\F_q(X)$-linear space, we denote $D_U = \diml  U$. We prove the claim by induction on $D_W$.	The case $D_W=0$ is immediate. Suppose that $D_W \ge 1$. Write $L = \lambda\cdot D_W$ and let $L' = \lambda^*\cdot D_W$, where \begin{equation}\label{eq:lambda'Def}\lambda^* = \ceil*{\frac{(D_W-1)\cdot \lambda}{D_W}+D_W}\eperiod\end{equation}
        Let $\balpha$ be sampled uniformly from $\F_q^n$. For $0\le i\le n$, denote $S_i = S[\Psi_{\ut i}, \balpha_{\ut i}]$ and $p_{U,i} = \pot_U(S_i, \Psi_{\uf {i+1}})$ (where $U\subseteq W$ is $F_q(X)$-linear). 

        Let $1\le t$ denote the minimal index at which $W$ is $S_t$-dead (if such an index does not exist, let $t = \infty$). Let $F$ denote the event that $t < \infty$ and $p_{W,t} < -L'$.

        Let $1\le s$ denote the minimal index in which at least one of the following two events occur:
        \begin{enumerate}
			\item $W$ is $S_s$-dead OR
			\item For some $S_s$-live $\F_q(X)$-linear space $\{0\}\ne U\subsetneq W$, there holds
			\begin{equation}\label{eq:tCondition}
				p_{U,s} > - \lambda^*\cdot D_U\eperiod
			\end{equation}
		\end{enumerate}
        Let $F'$ denote the event that $s < \infty$ and $p_{W,s} < -L'$. Observe that $F$ implies $F'$. Indeed, assume that $F$ holds. Clearly, $s\le t$, so $s < \infty$. By \cref{lem:GammaChange}, $p_{W,0},\dots, p_{W,n}$ is non-decreasing, so $p_{W,s}\le p_{W,t} < -L'$, implying $F'$. Therefore, by \cref{lem:LikelyToNotContainW},
        \begin{align*}
            \PROver{\balpha}{\overline{F'}} \le \PROver{\balpha}{\overline F} &\le  \binom{n}{\ceil{\frac{L-L'}{D_W}}}\cdot \inparen{\frac{(k'+\deg \Psi)\cdot D_W}q}^{\ceil{\frac{L-L'}{D_W}}} \\
            &\le \binom{n}{\ceil{\frac{L-L'}{D_W}}}\cdot \inparen{\frac{2g\cdot D_W}q}^{\ceil{\frac{L-L'}{D_W}}} 
            \\
            &=  \binom n {\ceil{\lambda - \lambda^*}}\cdot \inparen{\frac{2g\cdot D_W}{q}}^{\ceil{\lambda - \lambda^*}} \\
            &\le \inparen{\frac{2e\cdot n\cdot g\cdot D_W}{(\ceil{\lambda-\lambda^*})q}}^{\ceil{\lambda-\lambda^*}}\\
            &\le \inparen{\frac{4e\cdot n\cdot g\cdot D_W^2}{\lambda q}}^{\ceil{\lambda-\lambda^*}} &\text{by \cref{eq:lambdaLB,eq:lambda'Def}}\\
			&\le \inparen{\frac{4e\cdot n\cdot g\cdot D_W^2}{\lambda q}}^{\frac{\lambda}{D_W}-D_W-1} &\text{by \cref{eq:lambda'Def}} \\
			&\le \inparen{\frac{4e\cdot n\cdot g\cdot D_W^2}{\lambda q}}^{\frac{\lambda}{2D_W}} 
			\eperiod\numberthis \label{eq:PrE}
        \end{align*}

    We will show that, given $F'$, the event $S_n = \{0\}$ is highly likely. This statement, combined with \cref{eq:PrE}, will complete the proof.

    Henceforth, we condition on the event $F'$. Note that $\alpha_1,\dots,\alpha_s$ fully determine $F'$ and $s$. Therefore, the evaluation points $\alpha_{s+1},\dots,\alpha_n$ are unaffected by this conditioning and remain uniformly distributed and independent.

       We will assume that $S_s \ne \{0\}$, because otherwise $S_n \subseteq S_s = \{0 \}$, and we are done.
       We select an $S_s$-live $\F_q(X)$-linear subspace $U\subsetneq W$ as follows.
       If $W$ is $S_s$-dead, we set $U = \spnl  S_s$. Otherwise, by our assumption of $F'$ and definition of $s$, there exists an $S_s$-live subspace $\{0\} \ne U \subsetneq W$ with $p_{U,s} > -\lambda^*\cdot D_U$. We then take $U$ to be some inclusion-maximal subspace with this property.
       Note that in either case, $U \ne \{0 \}$ and therefore $\diml U \ge 1$.

       We now consider two events: 
            $S_n\cap U = \{0\}$ and 
            $S_n \subseteq U$.       
       We will prove that each of these events is very likely, and thus, so is their conjunction, namely, $S_n = \{0\}$.

        \subsubsection*{Probability of $S_n \cap U = \{0\}$}
        To prove that $S_n \cap U = \{0\}$ is very likely, we apply the induction hypothesis to the set $S' := S_s\cap U$ and the polynomial profile $\Psi' := \Psi_{\uf{s+1}}$. Recall that $U$ is $S_s$-live, which implies $U$ is also $S'$-live, therefore $U = \spnl (S' \cap U) = \spnl S'$ holds. Moreover $D_U < D_W$.

        Since $S$ is $k'$-bounded, so is $S'$. Similarly, $\deg \Psi' \le  g$. 

        Let $V\subseteq U$ be $\F_q(X)$-linear and $S'$-live. Denote $D_V \coloneqq \diml V$. Then,

        \begin{align*}
		\pot_V(S',\Psi') &= p_{V,s}\\ &\le p_{V,s-1} + D_V &\text{by the first part of \cref{lem:GammaChange}}\\&\le -\lambda^* \cdot D_V + D_V &\text{by definition of $s$}\\ &= -(\lambda^* -1 )\cdot D_V\eperiod 
        \end{align*}
        Also, $$\lambda^*-1 \ge \frac{(D_W-1)\cdot \lambda}{D_W} \ge 2\cdot(D_W-1)(D_W+1) \ge 2 D_U(D_U+1)\eperiod$$
        Hence, $\lambda^*-1$ satisfies \cref{eq:lambdaLB,eq:potentialLB}.
        Thus, the induction hypothesis is indeed valid here, and yields
       \begin{align*}
		\PROver{\balpha}{S_n\cap U \supsetneq \{0\}\mid F'} &\le \inparen{2^{D_U}-1}\cdot \inparen{ \frac{4e\cdot 2^{D_U} \cdot b^{2D_U} \cdot g\cdot n}{q(\lambda^*-1)}}^{\frac{\lambda^*-1}{2D_U}} \numberthis\label{eq:probSCapUTrivial}
        \end{align*}

        \subsubsection*{Probability of $S_n\subseteq U$}

	We turn to proving a lower bound on the probability of $S_n\subseteq U$. If $W$ is $S_s$-dead then $U = \spnl  S_s \supseteq S_n$, so the event holds deterministically. We therefore proceed under the assumption that $W$ is $S_s$-live, and that $U$ is an $S_s$-live $\F_q(X)$-linear subspace satisfying $p_{U,s} > -\lambda^* \cdot D_U$.

    Our strategy is to use $\Psi$ to construct a new polynomial profile $\Psi'$, such that applying the induction hypothesis to $\Psi'$ implies that $S_n\subseteq U$ with high probability. For each entry $\psi_i$ in $\Psi$, the corresponding entry $\psi'_i$ of $\Psi'$ is a polynomial map chosen so that the following diagram commutes:
    \[
    \begin{tikzcd}
    \mathbb{F}_q(X)^b \arrow[r, "\psi_i"] \arrow[d, "\pi"'] & \mathbb{F}_q(X)^a \arrow[r, "\chi_i"] & \mathbb{F}_q(X)^r \\
    \mathbb{F}_q(X)^{b - d_U} \arrow[rru, "\psi_i'"']
    \end{tikzcd}\eperiod
    \]
    Here, $\pi$ and $\chi_i$ are polynomial maps whose kernels are  $U$ and $\psi_i(U)$, respectively.

    In order to apply the induction hypothesis to $\Psi'$, we also need to control the degrees of the polynomial maps $\pi$ and $\psi'$. This construction is achieved by \cref{claim:Cramer,claim:MapToKernel,claim:MapOfPsi,claim:polynomialMapZeroes}, which rely on notions from \cref{def:polyMap}. 

            \begin{claim}\label{claim:Cramer}
                Let $\mT\in \F_q[X]^{p\times e}$ ($p \ge e$) be a full-rank (over $\F_q(X)$) matrix of $d$-bounded polynomials ($d\in \N$). Then, there is a full-rank matrix $\mT^*\in \F_q[X]^{(p-e)\times p}$ of $(e\cdot d)$-bounded polynomials such that $\ker \mT^* = \im \mT$.
            \end{claim}
            \begin{proof}
                Suppose without loss of generality that $\mT$ can be written as a block matrix $\inbrak{\begin{array}{c}
					\mT_1\\
					\hline
					\mT_2
			\end{array}}$ where $\mT_1 \in \F_q[X]^{e\times e}$ has full-rank over $\F_q(X)$, and $\mT_2\in \F_q[X]^{(p-e)\times e}$.

			Let $\mT^*\in \F_q(X)^{(p-e)\times p}$ be the block matrix $\det(\mT_1)\cdot\inbrak{\begin{array}{c|c}
					-\mT_2\mT_1^{-1}&\mI_{p-e}
			\end{array}}$. Observe that $\ker \mT^* = \im \mT$. By Cramer's Rule, every entry of $\det(\mT_1)\cdot \mT_1^{-1}$ is a polynomial of degree at most $(e-1)\cdot d$. Thus, every entry of $\mT^*$ is a polynomial of degree at most $e\cdot d$.
            \end{proof}
		\begin{claim}\label{claim:MapToKernel}
			There exists an $\F_q(X)$-linear polynomial map $\pi \colon \F_q(X)^b\to \F_q(X)^{b-D_U}$ with $\ker \pi = U$ and $\deg \pi \le D_U\cdot k'$.

		\end{claim}
		\begin{proof}
			Since $U$ is $S_s$-live, there is a matrix $\mT\in \F_q(X)^{b\times D_U}$ such that $\im \mT = U$ and the columns of $\mT$ belong to $S_s$. In particular, because $S_s$ is a $k'$-bounded space, every entry of $\mT$ is a polynomial in $\F_q[X]$ of degree at most $k'$. Therefore, $\mT$ satisfies the conditions of \cref{claim:Cramer} with $p=b, e=D_U$, and $d=k'$. Let $\mT^*$ be the matrix guaranteed by \cref{claim:Cramer}. Take $\pi$ to be the $\F_q(X)$-linear map that $\mT^*$ represents in the standard basis. The claim follows immediately.
		\end{proof}

            \begin{claim}\label{claim:MapOfPsi}
                Let $\pi$ be as in $\cref{claim:MapToKernel}$ and let $\psi \colon \F_q(X)^b\to \F_q(X)^a$ ($a\le b$) be an $\F_q(X)$-linear polynomial map of degree $d$ and rank $a$. Then, there exist $r\in \N$ and $\F_q(X)$-linear maps $\psi' \colon \F_q(X)^{b-d_U}\to \F_q(X)^{r}$ and $\chi \colon \F_q(X)^a\to \F_q(X)^{r}$ with the following properties:
                \begin{itemize}
                    \item $\chi\circ \psi = \psi'\circ \pi$.
                    \item $\psi'$ is a polynomial map of degree at most $\max\{b\cdot d,b\cdot D_U\cdot k'\}$
                    \item $\ker \chi = \psi(U)$
                \end{itemize}
            \end{claim}
            \begin{proof}
                In this proof, all dimensions and ranks are with regard to the field $\F_q(X)$.
                Let $\mM_\pi \in \F_q[X]^{(b-D_U)\times b}$ and $\mM_\psi \in \F_q[X]^{a\times b}$ be full-rank matrices representing $\pi$ and $\psi$ in the standard basis, respectively. By \cref{claim:MapToKernel} we know that every entry in $\mM_\pi$ is a polynomial having degree at most $D_U\cdot k$. By hypothesis, we assume that every entry in $\mM_\psi$ is a polynomial having degree at most $d$. By a slight abuse of notation, we will use $\spnl (\mM)$ to denote the $\F_q(X)$-span of the columns of some matrix $\mM$.

                Let 
                \begin{align*}
                r&\coloneqq \diml\inparen{\spnl(\mM_\psi^\intercal) \cap \spnl(\mM_\pi^\intercal)} \\
                &= b - \diml\inparen{\ker \psi + \ker \pi} \\
                &= b - \diml(\ker \psi) - \diml(\ker \pi) + \diml(\ker \psi\cap \ker \pi) \\
                &= a - \inparen{\diml(\ker \pi) + \diml\inparen{\ker \psi\cap \ker \pi}} = a - \inparen{\diml(U) - \diml\inparen{\ker \psi \cap U}} \\ &= a - \diml\inparen{\psi(U)}\eperiod
                \end{align*}
                The first equality follows by the rank-nullity theorem and De-Morgan's law.
                 Let $\mZ \in \F_q[X]^{(b-D_U+a)\times b}$ denote the block matrix 
                 $\inbrak{\begin{array}{c}
					\mM_\pi\\
					\hline
					\mM_\psi
			\end{array}}$.
                Define $e \coloneqq b-D_U+a-r \le b$ and note that $\rankl \mZ = e$. Let $\mT\in \F_q[X]^{(b-D_U+a)\times e}$ be a submatrix of $\mZ$ obtained by selecting a set of $e$ columns so that $\rankl \mT = e$. Let $\mT^*\in \F_q[X]^{r\times (b-D_U+a)}$ be the matrix guaranteed by \cref{claim:Cramer}, corresponding to $\mT$. In particular, $\ker \mT^* = \spnl (\mT) = \spnl (\mZ)$.

                Write $\mT^*$ as a block matrix $\inbrak{\begin{array}{c|c}
					\mP&\mQ
			\end{array}}$
                where $\mP\in \F_q[X]^{r\times (b-D_U)}$ and $\mQ\in \F_q[X]^{r\times a}$. We take $\psi'$ and $\chi$ to be the $\F_q(X)$-linear maps represented by $\mP$ and $-\mQ$, respectively. We turn to show that $\psi'$ and $\chi$ satisfy the required properties.

                The first property is equivalent to $-\mQ\mM_\psi = \mP\mM_\pi$. This is true since $\mT^*\mT = 0$, thus, implying $\mT^*\mZ=0$. Therefore,
                $$0 = \mT^*\mZ = \mP\mM_\pi+\mQ\mM_\psi\eperiod$$
                For the second condition, \cref{claim:Cramer} guarantees that each entry of $\mT^*$, and thus also of $\mP$, has degree at most $\max\{d,D_U\cdot k'\}\cdot e \le \max\{b\cdot d,b\cdot D_U\cdot k'\}$.

                For the third condition, let $u\in U$, and recall that $U = \ker \pi$. Then,
                $$0 = \mT^* \mZ u = \mP\mM_\pi u + \mQ \mM_\psi u = \psi'(\pi(u)) +  \chi(\psi(u)) = \chi(\psi(u))\ecomma$$
                where $\psi'(\pi(u))=0$ as $u \in \ker \pi$, so $\psi(U)\subseteq \ker \chi$. On the other hand, suppose that $x\in \F_q(X)^a$ such that  $\chi(x)=0$. Let $y \coloneqq \bz_{b-D_U}\circ x$ denote the concatenation of $b-D_U$ zeros and $x$. Then, $\mT^*y = \mQ x = \chi(x) = 0$, so $y\in \ker \mT^* = \im \mZ$. Let $w\in \F_q(X)^b$ be such that $\mZ w = y$. Then, $\pi(w) = \mM_\pi w = 0$ and $\psi(w) = \mM_\psi w = x$ hold by the definition of $y$. This implies that $w\in \ker \pi = U$ and $x\in \psi(U)$.
            \end{proof}

            \begin{claim}\label{claim:polynomialMapZeroes}
                Let $\chi \colon \F_q(X)^a\to \F_q(X)^r$ be a polynomial map. Let $\alpha \in \F_q$ and $p\in \F_q[X]^b$ be such that $p(\alpha) = 0$. Then, $\chi(p)(\alpha) = 0$.
            \end{claim}
            \begin{proof}
                It suffices to prove the claim for $r=1$. Write $\chi(p) = \sum_{i=1}^a q_i p_i$ where $q_i \in \F_q[X]$ for each $i$. Then, $$\chi(p)(\alpha) = \sum_{i=1}^a q_i(\alpha)\cdot p_i(\alpha) = \sum_{i=1}^a q_i(\alpha)\cdot 0 = 0\eperiod$$
            \end{proof}

            To lower bound the probability of $S_n\subseteq U$ we apply the induction hypothesis to a space of polynomials and a polynomial profile that we now construct. Let $\pi$ be as in \cref{claim:MapToKernel} and let $S'=\pi(S_s)$. Recall that $\Psi$ is a $b$-local polynomial profile, therefore for every $i$ such that $s+1 \le i\le n$, we have a polynomial map $\psi_i \colon \F_q(X)^b \to \F_q(X)^{a_i}$, for some $0 \le a_i \le b$. By applying \cref{claim:MapOfPsi} for $\pi$ and every $\psi_i$ for $s+1 \le i \le n$, we see that there exists an $r_i$ and $\F_q(X)$-linear maps $\psi_i' \colon \F_q(X)^{b-D_U}\to \F_q(X)^{r_i}$ and $\chi_i \colon \F_q(X)^{a_i}\to \F_q(X)^{r_i}$. Let $\Psi' = \inparen{\psi'_{s+1},\dots, \psi'_n}$. Let $\balpha' = \balpha_{\uf{s+1}}$.

            We claim that 
            \begin{equation}\label{eq:sn-empty-implies-within-u}
                S'[\Psi',\balpha'] = \{0\} \quad \implies \quad S_n\subseteq U\eperiod
            \end{equation}
            Indeed, suppose that $S'[\Psi',\balpha'] = \{0\}$ and let $p \in S_n$. We need to show that $p\in U$. Let $p' = \pi(p)$ and let $i$ be such that $s+1\le i\le n$. Since $p \in S_n$, we have $\psi_i(p)(\alpha_i) = 0$. Therefore,
            $$\psi'_i(p')(\alpha_i) = ((\psi'_i\circ \pi) (p))(\alpha_i) = ((\chi_i\circ \psi_i)(p))(\alpha_i) = \chi_i (\psi_i(p))(\alpha_i) = 0\eperiod$$
            Where the last equality is due to \cref{claim:polynomialMapZeroes}. Therefore, $p' \in S'[\Psi',\balpha']$, whence $\pi(p) = p' = 0$. Thus, $p\in \ker \pi = U$.

            \paragraph{Applying the induction hypothesis: }
            Observe that because $W$ is $S_s$-live and $S_s \subseteq S \subseteq W$, $\spnl S_s = W$ holds. Therefore $\spnl S' = \spnl \pi(S_s) = \pi( \spnl S_s) = \pi(W)$. Recall that $\diml U \ge 1$, let $W' := \spnl  S' = \pi(W)$ and note that $\diml  W' = \diml W - \diml (\ker \pi \cap W) = \diml W - \diml U < \diml W$. We will now apply the induction hypothesis to $S'$, $\Psi'$ and $W'$, after showing that they satisfy the required conditions. First, note that $W'$ satisfies $W' = \spnl S'$ by definition, and we just showed that $\diml W' < \diml W$.

            We now prove that for every $S'$-live $\F_q(X)$-linear space $V'\subseteq W'$, the following holds
            \[
                \pot_{V'}(S',\Psi') \le -\lambda^*\cdot D_{V'} \eperiod
            \]
            This is easily seen to be true when $V'$ is the zero subspace, hence assume that it is not.
            Let $U' = \pi^{-1}(V')$ and note that $U\subset U'\subseteq W$. We now prove the following claim:
            \begin{claim}\label{claim:piIntersection}
                Let $S_s, S', V', U'$ be as defined above. The following holds:
                \begin{equation}
                \pi(S_s \cap U') = \pi(S_s) \cap \pi(U') = S' \cap V'\eperiod
                \end{equation}
            \end{claim}
            \begin{proof}
                The second equality is true by definitions of $S', U'$, so we prove the first equality. The containment $\pi(S_s \cap U') \subseteq \pi(S_s) \cap \pi(U')$ is easy to see. The other containment is proved as follows: fix a $p \in \pi(S_s) \cap \pi(U')$. Because $p \in S'$, there is a $q \in S_s$ so that $p = \pi(q)$. Now $q$ must also be in $U'$, because if not, then $\pi(q) \not\in V'$ by the definition of $U'$, which would contradict the fact that $\pi(q) = p \in V'$. 
            \end{proof}

            Combining \cref{claim:piIntersection} and the following two equations:
            \[
                \ker \pi \cap (S_s \cap U') = U \cap S_s \cap U' = U \cap S_s
            \]
            \[
                \dims (\pi(S_s \cap U')) = \dims (S_s \cap U') - \dims (\ker \pi \cap (S_s \cap U')) \ecomma
            \]
            we see that the following is true
            \begin{equation}\label{eq:smallDimS'V'}
                \dims (S'\cap V') = \dims (S_s\cap U') - \dims (U \cap S_s)\eperiod
            \end{equation}
            Observe that we have used $\dims$ (and not $\diml$) in the previous sentence. Because the spaces and maps we are considering are $\F_q$-linear (in fact, they are $\F_q(X)$-linear) subspaces and maps respectively, we can apply rank-nullity theorem while viewing them as linear over the field $\F_q$.

            Note that for $s+1\le i\le n$, 
            \begin{align}
            \diml (\psi_i'(V')) &= \diml (\psi'_i\circ\pi(U'))) = \diml (\chi_i\circ \psi_i(U')) \nonumber\\&= \diml (\psi_i(U')) - \diml (\psi_i(U')\cap \ker \chi_i) = \diml (\psi_i(U')) - \diml (\psi_i(U)) \label{eq:dimOfPsiPrimeVPrime}
            \end{align}
            where we used the fact that $\ker \chi_i = \psi_i(U)$ for the last equality.
            Now, by \cref{eq:smallDimS'V'} and \cref{eq:dimOfPsiPrimeVPrime} we have
            \begin{align*}
                \pot_{V'}(S',\Psi') &= \dims(S' \cap V') - \rf_{V'}(\Psi') \\
                &= \dims(S_s\cap U')- \dim(U \cap S_s) - \rf_{U'}(\Psi_{\uf {s+1}}) + \rf_{U}(\Psi_{\uf {s+1}}) \\
                &= p_{U',s} - p_{U,s}\eperiod
            \end{align*}

            We will now prove
            \[
                p_{U',s} \le -\lambda^* D_{U'}\eperiod
            \]
            Observe that because $U$ is an inclusion-maximal $S_s$-live subspace such that $p_{U,s} > -\lambda^* \cdot D_U$, it is suffices to prove that $U'$ is $S_s$-live. Note that $\spnl(S' \cap V') = V'$ because $V'$ is $S'$-live, and by \cref{claim:piIntersection} and $\F_q(X)$-linearity of $\pi$, we see that
            \begin{equation}\label{eq:V'EqualsPiOfSsU}
                V' = \spnl(S' \cap V') = \spnl(\pi(S_s \cap U')) = \pi(\spnl(S_s \cap U')) \eperiod
            \end{equation}
            Because $U$ is $S_s$-live, $\spnl(S_s \cap U')$ contains $\ker \pi = U$ and therefore we have that $\pi^{-1}(\pi(\spnl(S_s \cap U'))) = \spnl(S_s \cap U')$. This together with \cref{eq:V'EqualsPiOfSsU} implies $\spnl(S_s \cap U') = \pi^{-1}(V') = U'$, and so $U'$ is $S_s$-live.

            Therefore,
            $$\pot_{V'}(S',\Psi') \le -\lambda^* (D_{U'} - D_{U}) = -\lambda^*\cdot D_{V'}\eperiod$$

            The last equality holds by the rank-nullity theorem applied on the subspace $U'$ and map $\pi$. By \cref{eq:lambdaLB} applied to $\lambda$, and \cref{eq:lambda'Def},
            $$\lambda^* \ge \frac{(D_W-1)\cdot \lambda}{D_W}\ge \frac{2 D_W(D_W+1)(D_W-1)}{D_W} = 2(D_W+1)(D_W-1)\ge 2(D_{W'}+1)\cdot D_{W'},$$
            so $\lambda^*$ satisfies \cref{eq:lambdaLB} with regard to $D_{W'}$.
            Recall that $g$ was equal to $\max(\deg \Psi, b \cdot k')$, and set $\hat{k} \coloneqq b\cdot D_U \cdot k'$ and $\hat{g} \coloneqq b^2g$ . By \cref{claim:Cramer} and  \cref{claim:MapToKernel}, $S'$ is $\hat{k}$-bounded. By \cref{claim:MapOfPsi}, 
            \begin{align*}\deg \Psi'\le \max\inset{b\cdot \deg \Psi, b\cdot D_U\cdot k'} \le bg\eperiod
            \end{align*}
            Note that $\hat{g} \ge \max\inset{\deg \Psi', b\cdot \hat{k}}$.


            We have now proven that $S', \Psi',$ and $W'$ indeed satisfy the required conditions, with $\hat{g}, \lambda^*, \hat{k}$ being the new values for $g, \lambda, k'$ respectively, and therefore by \cref{eq:sn-empty-implies-within-u},

            \begin{align*}
                \PROver{\balpha}{S_n\not\subseteq U\mid F'} &\le \PROver{\balpha}{S'[\Psi',\balpha']\supsetneq \{0\}\mid F'} 
                \\&\le \inparen{2^{D_{W'}}-1}\cdot \inparen{ \frac{4e\cdot 2^{D_{W'}} \cdot b^{2D_{W'}}\cdot \hat{g}\cdot (n-s)}{q\cdot \lambda^*}}^{\frac{\lambda^*}{2D_{W'}}} 
                \\&= \inparen{2^{D_{W'}}-1}\cdot \inparen{ \frac{4e \cdot 2^{D_{W'}}\cdot b^{2D_{W'}}\cdot b^2\cdot g\cdot (n-s)}{q\cdot\lambda^*}}^{\frac{\lambda^*}{2D_{W'}}}
                \numberthis\label{eq:probSnInU}
            \end{align*}

        \subsubsection*{Putting it All Together - Probability of $S_n = \{0\}$}
        \cref{eq:probSCapUTrivial,eq:probSnInU} yield
        \begin{align*}
            \PROver{\balpha}{S_n\ne \{0\}\mid F'} &\le \PROver{\balpha}{S_n\cap U \ne \{0\}\mid F'} + \\
            &\phantom{{}={}}\PROver{\balpha}{S_n\not\subseteq U \mid F'} 
            \\
            &\le  \inparen{2^{D_U}-1}\cdot \inparen{ \frac{4e \cdot 2^{D_U} \cdot b^{2D_U} \cdot g\cdot n}{q(\lambda^*-1)}}^{\frac{\lambda^*-1}{2D_U}}  + \\ 
            &\phantom{{}={}}\inparen{2^{D_{W'}}-1}\cdot \inparen{ \frac{4e \cdot 2^{D_{W'}} \cdot b^{2(D_{W'}+1)} \cdot g\cdot (n-s)}{q\cdot\lambda^*}}^{\frac{\lambda^*}{2D_{W'}}}
            \\
            &\le \inparen{2^{D_W}-2}\cdot \inparen{ \frac{4e\cdot 2^{D_W-1} \cdot b^{2D_W} \cdot g\cdot n}{q(\lambda^*-1)}}^{\frac{\lambda^*-1}{2(D_W-1)}} 
            \\
            &\le \inparen{2^{D_W}-2}\cdot \inparen{ \frac{4e\cdot 2^{D_W} \cdot b^{2D_W} \cdot g\cdot n}{q\cdot \lambda}}^{\frac{\lambda}{2D_W}}
        \end{align*}
        The second last inequality is true because $D_{W'}<D_W$, $D_U<D_W$ are true, and the last inequality is true by \cref{eq:lambda'Def} and the fact that $D_W>1$ holds (recall that $U \subsetneq W$ and $U$ is a non-trivial subspace).

        Recall that \cref{eq:PrE} yields an upper bound on $\PROver{\balpha}{\overline{F'}}$. Therefore,
        \begin{align*}
            \PROver{\balpha}{S_n\ne \{0\}} &\le \PROver{\balpha}{\overline{F'} \land S_n\ne \{0\}} + \PROver{\balpha}{ S_n\ne \{0\} \land F'} \\
            &\le \PROver{\balpha}{\overline{F'}} + \PROver{\balpha}{F'}\cdot \PROver{\balpha}{ S_n\ne \{0\}  \mid F'} \\
            &\le \PROver{\balpha}{\overline{F'}} + \PROver{\balpha}{S_n\ne \{0\}\mid F'} \\ &\le
            \inparen{\frac{4e\cdot D_W^2\cdot g\cdot n}{q\cdot \lambda}}^{\frac{\lambda}{2D_W}}   + \inparen{2^{D_W}-2}\cdot \inparen{ \frac{4e \cdot 2^{D_W} \cdot b^{2D_W}\cdot g\cdot n}{q\cdot \lambda}}^{\frac{\lambda}{2D_W}} \\
            &\le \inparen{2^{D_W}-1}\cdot \inparen{ \frac{4e \cdot 2^{D_W} \cdot b^{2D_W}\cdot g\cdot n}{q\cdot \lambda}}^{\frac{\lambda}{2D_W}}\ecomma
        \end{align*}
        which yields the lemma.
        \end{proof}
